<?php
declare(strict_types=1);
namespace Moves\Services\Talk;
use Moves\Boot\Connection;
use PDO;
final class TalkInboundService{
 public function receiveWhatsApp(array $payload):int{$external=mb_substr(trim((string)($payload['external_id']??'')),0,191);$phone=preg_replace('/\D+/','',(string)($payload['from']??''))??'';$body=mb_substr(trim((string)($payload['body']??'')),0,4000);if($external===''||$phone==='')throw new \RuntimeException('Mensagem WhatsApp inválida.');$pdo=Connection::getInstance();$dup=$pdo->prepare("SELECT id FROM talk_messages WHERE external_id=? LIMIT 1");$dup->execute([$external]);if($dup->fetchColumn())return 0;$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT id FROM talk_contacts WHERE phone=? LIMIT 1");$q->execute([$phone]);$contactId=(int)($q->fetchColumn()?:0);if($contactId===0){$name=mb_substr(trim((string)($payload['push_name']??'')),0,160);$i=$pdo->prepare("INSERT INTO talk_contacts(name,phone,external_id,channel,metadata) VALUES(?,?,?,'whatsapp',?)");$i->execute([$name!==''?$name:null,$phone,$phone,json_encode(['source'=>'baileys'],JSON_THROW_ON_ERROR)]);$contactId=(int)$pdo->lastInsertId();}$q=$pdo->prepare("SELECT id FROM talk_conversations WHERE contact_id=? AND channel='whatsapp' ORDER BY id DESC LIMIT 1");$q->execute([$contactId]);$conversationId=(int)($q->fetchColumn()?:0);if($conversationId===0){$i=$pdo->prepare("INSERT INTO talk_conversations(contact_id,channel,external_id,status,last_message_at) VALUES(?,'whatsapp',?,'open',NOW())");$i->execute([$contactId,'wa:'.$phone]);$conversationId=(int)$pdo->lastInsertId();}$q=$pdo->prepare("SELECT id,status FROM talk_tickets WHERE conversation_id=? ORDER BY id DESC LIMIT 1");$q->execute([$conversationId]);$ticket=$q->fetch(PDO::FETCH_ASSOC);$ticketId=(int)($ticket['id']??0);if($ticketId===0||($ticket['status']??'')==='closed'){$queueId=(int)($pdo->query("SELECT id FROM talk_queues WHERE status='active' ORDER BY id LIMIT 1")->fetchColumn()?:0);if($queueId===0){$pdo->exec("INSERT IGNORE INTO talk_departments(name,slug,status) VALUES('Atendimento','atendimento','active')");$departmentId=(int)$pdo->query("SELECT id FROM talk_departments WHERE slug='atendimento' LIMIT 1")->fetchColumn();$s=$pdo->prepare("INSERT IGNORE INTO talk_queues(department_id,name,slug,status,auto_assign_after_seconds) VALUES(?,'Atendimento geral','atendimento-geral','active',30)");$s->execute([$departmentId]);$queueId=(int)$pdo->query("SELECT id FROM talk_queues WHERE slug='atendimento-geral' LIMIT 1")->fetchColumn();}$protocol='TALK-'.date('Ymd').'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);$i=$pdo->prepare("INSERT INTO talk_tickets(conversation_id,protocol,queue_id,status,priority,source,queued_at,last_activity_at) VALUES(?,?,?,'queued','normal','whatsapp',NOW(),NOW())");$i->execute([$conversationId,$protocol,$queueId>0?$queueId:null]);$ticketId=(int)$pdo->lastInsertId();}$i=$pdo->prepare("INSERT INTO talk_messages(conversation_id,ticket_id,sender_type,external_id,direction,type,body,metadata,sent_at) VALUES(?,?,'contact',?,'inbound',?,?,?,NOW())");$i->execute([$conversationId,$ticketId,$external,mb_substr((string)($payload['type']??'text'),0,50),$body,json_encode(['channel'=>'whatsapp','push_name'=>$payload['push_name']??null],JSON_UNESCAPED_UNICODE)]);$pdo->prepare("UPDATE talk_conversations SET status='open',last_message_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$conversationId]);$pdo->prepare("UPDATE talk_tickets SET last_activity_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$ticketId]);$pdo->commit();return $ticketId;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}